   [61]={next_id=62, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="艾丽西亚……那孩子在听到手术的时候，虽然脸上依旧是一副自信的样子——", msg_color="", msg_size=0, talker="伊西丝", audio="", img="arts/ui/bg/story/storybg_9_102.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "7110", 2, 0, 10, 204.5}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [62]={next_id=63, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="但我能看得出来，她其实很害怕。", msg_color="", msg_size=0, talker="伊西丝", audio="", img="arts/ui/bg/story/storybg_9_102.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "7110", 2, 0, 10, 204.5}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [63]={next_id=64, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="伊西丝瞥向远处正与医疗科医生配合着的艾丽西亚，目光深邃而复杂。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_9_102.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "7110", 2, 0, 10, 204.5}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,0}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [64]={next_id=65, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="我预想过她拒绝的可能，如果真的发生了，哪怕当个坏人，我也要想尽办法让她接受这个手术。", msg_color="", msg_size=0, talker="伊西丝", audio="", img="arts/ui/bg/story/storybg_9_102.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "7110", 2, 0, 10, 204.5}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [65]={next_id=66, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="但她依然强忍着心里的恐惧，在我面前答应了手术……从那时起，我就明白，这孩子已经长大了。", msg_color="", msg_size=0, talker="伊西丝", audio="", img="arts/ui/bg/story/storybg_9_102.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "7110", 2, 0, 10, 204.5}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [66]={next_id=67, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="星源共鸣的来源是人的精神，所以手术成功的关键取决于她本身的意志——而她也向我证明了，她的意志有多坚强。", msg_color="", msg_size=0, talker="伊西丝", audio="", img="arts/ui/bg/story/storybg_9_102.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "7110", 2, 0, 10, 204.5}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [67]={next_id=68, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="我很欣慰，也很心疼，她虽然忍受住了内心的脆弱，却没有地方将它发泄出来……", msg_color="", msg_size=0, talker="伊西丝", audio="", img="arts/ui/bg/story/storybg_9_102.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "7110", 2, 0, 10, 204.5}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [68]={next_id=69, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="长期以往下去，对手术也会有严重影响。", msg_color="", msg_size=0, talker="伊西丝", audio="", img="arts/ui/bg/story/storybg_9_102.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "7110", 2, 0, 10, 204.5}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [69]={next_id=70, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="伊西丝说完这些，脸上的凝重却在逐渐消失。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_9_102.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "7110", 2, 0, 10, 204.5}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,0}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [70]={next_id=71, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="她看向你，露出一抹不易察觉的微笑。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_9_102.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "7110", 2, 0, 10, 204.5}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,0}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [71]={next_id=72, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="……不过现在看来，她已经找到了能让她发泄的出口，找到了那个能带给她勇气的人。", msg_color="", msg_size=0, talker="伊西丝", audio="", img="arts/ui/bg/story/storybg_9_102.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "7110", 2, 0, 10, 204.5}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [72]={next_id=73, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="这是她自己努力的结果，我只是选择支持她。", msg_color="", msg_size=0, talker="玩家名字", audio="", img="arts/ui/bg/story/storybg_9_102.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "7110", 2, 0, 10, 204.5}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,0}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
